from assessment_writer import write_review
def compact(sid,title,rows,appraisal):
    write_review(sid,title,[(a,b.split(' | '),c) for a,b,c in rows],appraisal)

compact('COND-C02-COVIDOUT-2022','COVID-OUT acute report: negative primary endpoint and promising secondary findings',[
('Methods, End Points','Prevent severe acute COVID-19 with early outpatient medication. | Prespecified composite through day 14. | Hypoxemia, emergency visit, hospitalization or death.','Secondary endpoints do not replace the primary.'),
('Methods; Figure 1; Table 1','Adults 30–85 with overweight or obesity and recent COVID-19. | Six US institutions, remote enrollment; positive test within three days and symptoms within seven. | 1431 randomized; 1323 mITT: 663 metformin, 660 control; 52.2% vaccinated.','Median age 46; limited applicability to current immune backgrounds.'),
('Treatment','Immediate-release metformin. | Oral escalation to 1500 mg/day over six days, 14 days total. | Factorial fluvoxamine, ivermectin or matched placebo assignments. | Primary day 14; hospitalization/death also day 28.','No comparison of IR versus ER.'),
('Randomization','Concurrent matched placebo for metformin. | Equal probability among open groups, site-stratified. | Pregenerated mass-weighted urn sequence. | Blinded participants, clinicians and outcome assessors; similar pill burden. | December 2020–January 2022, with factorial expansion May 2021.','Comparisons between different drugs’ crude rates are invalid because enrollment periods differ.'),
('End Points; statistics','Primary four-part composite; health-care component and symptoms secondary. | Home oxygen saturation, medical-record verification and symptom diaries. | Day 14 primary. | Composite mixes a noisy physiologic measure with major clinical events. | Planned 35% relative reduction, not a validated universal MCID.','Oximeter limitations weaken the endpoint but do not justify retrospectively calling the trial primary-positive.'),
('Table 2; Results','Primary 154/652 metformin versus 179/653 control; emergency visit/hospitalization/death 27/652 versus 48/655. | Full mITT denominators 663/660; displayed event fractions are observed complete cases. | Adjusted primary OR .84, 95% CI .66–1.09, P=.19. | Secondary health-care composite OR .58, CI .35–.94; day-14 hospitalization/death OR .47, CI .20–1.11. | Day-28 hospitalization/death 8/596 versus 19/601; secondary CIs not adjusted for multiplicity.','No primary benefit demonstrated; secondary signals warrant further testing.'),
('Methods; Discussion','108 excluded from mITT because no trial drug received. | Primary follow-up missing about 1.4%; symptom diary missing about 25%. | Drug discontinuation recorded; current registry contains six factorial-arm counts. | ITT sensitivity analyses described separately from mITT. | mITT with multiple imputation; symptoms not imputed. | Individual participant.','Factorial arms are not independent trials.'),
('Safety; current NCT04510194 results','Non-COVID events solicited through day 14; serious events through day 28 in registry. | Registry six-arm safety populations total 1323. | No medication-related serious event reported; one all-cause death occurred in a metformin/ivermectin recipient. | Metformin-only discontinuations 56/284 versus double-placebo 49/295; combination-arm counts differ. | Short treatment and acute follow-up.','These arm-specific discontinuations are not the entire factorial metformin effect.'),
('Statistics; Discussion','Remote oximetry, mITT exclusions and missing symptom diaries. | Concurrent randomization and adjusted co-medication/vaccination analyses reduce confounding. | Registered protocol/SAP recovered; report explicitly identifies secondary analyses. | No multiplicity correction for secondary outcomes. | Hospitalization/death events rare with wide intervals. | Wording about symptom reduction is awkward in Results; figures and conclusion indicate no symptom benefit.','Use the explicit conclusion and endpoint hierarchy.'),
('Eligibility; Discussion','Early acute outpatient infection in overweight/obese adults. | Fourteen-day IR course. | Not established long-COVID treatment or a comparison with authorized antivirals. | Variants, vaccination and enrollment criteria limit extrapolation.','Long-term follow-up is a separate outcome in the same trial.'),
('NCT04510194','COVID-OUT randomized family. | P-COVIDOUT-2023 long-term and MF-COVID-VIRAL-2024 virologic reports. | Overlapping participants; count once. | Current inventory and linked registry.','Multiple reports increase outcome detail, not independent replication.'),
('Byline; acknowledgments','Carolyn Bramante and COVID-OUT collaborators. | US investigator-led multicenter remote trial. | Parsemus, Rainwater, Fast Grants and UnitedHealth Group Foundation; stated no funder role. | Apotex fluvoxamine placebo; Edenbridge ivermectin active/placebo; metformin donor not established here. | GAP: Separate original NEJM disclosure forms not recovered; later related report provides named investigator disclosures.','Do not substitute later disclosures for exact original forms.'),
('Full report; registry/protocol assets','NEJM 2022, DOI 10.1056/NEJMoa2201662. | Full text, tables and current trial record inspected. | Protocol/SAP recovered; original acute supplement not fully audited. | NCT04510194. | Long-term 2023 correction belongs to the companion report, not an acute primary-result correction. | November 3–4, 2026.','Preserve report-specific version history.'),
('G-METFORMIN acute infection','Acute severity and symptom claims. | Primary null; secondary clinical benefit signal. | Authors’ cautious primary conclusion is retained despite stronger later commentary.','No claim of proven general antiviral replacement.'),
('Synthesis','Early metformin did not significantly reduce the original primary composite. | Whether secondary benefits generalize remains uncertain. | Independent current-population trials with prespecified clinical endpoints matter.','Guide separates this from long-COVID prevention.')
], 'A well-blinded factorial trial with a negative primary outcome, a noisy oximetry component and favorable but multiplicity-unadjusted secondary outcomes. It is one trial family shared with the viral-load and long-term reports.')

compact('MF-COVID-VIRAL-2024','COVID-OUT virology: lower RNA load, not proof of reduced transmission',[
('Methods, Clinical and Virologic End Points','Assess metformin’s effect on SARS-CoV-2 nasal RNA load. | Prespecified secondary virologic endpoint, baseline-adjusted follow-up viral load. | Biological antiviral signal.','Clinical efficacy requires its own outcomes.'),
('Table 1; Results','COVID-OUT adults with acute infection, overweight or obesity. | Optional self-collected nasal-swab substudy. | 999 of 1323 mITT participants: 504 metformin and 495 placebo; 945 day-1, 871 day-5 and 775 day-10 samples.','Optional participation is a selection step.'),
('Methods','Immediate-release metformin. | 500 mg day 1, 500 mg twice daily days 2–5, 500/1000 mg days 6–14. | Factorial co-medication assignments adjusted in analysis. | Swabs days 1, 5 and 10.','Exact regimen is a description, not a recommendation.'),
('Study design','Concurrent placebo assignments in COVID-OUT. | Parent factorial randomization. | Randomized treatment, not randomized swab participation. | Participants, care providers, investigators and outcome assessors blinded. | Enrollment December 2020–January 2022.','Not an independent second randomized trial.'),
('Laboratory and statistical methods','Secondary log viral load; detectability and rebound additional measures. | RT-qPCR N1/N2 targets calibrated to digital PCR. | Days 5 and 10 adjusted for baseline. | RNA surrogate; not viral culture, transmission or symptoms. | NR: No validated RNA-change threshold for clinical benefit established here.','RNA copies do not directly measure infectiousness.'),
('Results; Figures 1–3','Average viral load declined in both groups; adjusted reduction greater with metformin. | 504/495 substudy participants; repeated swabs are not additional patients. | Between-group difference −.56 log10 copies/mL, CI −1.05 to −.06, P=.027. | Day 5 −.47, CI −.93 to −.014; day 10 −.64, CI −1.42 to .13. | Detectability OR .72, CI .55–.94; rebound 3.28% versus 5.95%, OR .68, CI .36–1.29.','The rebound interval includes no effect; the stronger plain-language summary overstates that certainty.'),
('Methods; Results','Day-10 sample availability lower than baseline. | 78 lacked materials for all days and three for follow-up due to supply shortages; multiple imputation used. | Drug adherence inherited from parent, not separately established by swabs. | Optional sample providers define substudy; nonproviders excluded from its cohort. | Tobit model for left censoring, clustered SEs for repeated observations. | Participant, with repeated nasal specimens.','Imputation assumptions and self-collection variability matter.'),
('Parent safety report; virology methods','No distinct safety surveillance described for viral analysis. | Parent mITT safety population, not just 999 swab providers. | Parent reports no medication-related serious event. | Parent discontinuations, not new independent counts. | Fourteen-day treatment; parent serious-event follow-up through day 28.','This paper cannot establish long-term safety.'),
('Statistics; Discussion','Optional sampling, missing swabs and lower-limit censoring. | Treatment randomized; sample availability and collection quality may bias substudy. | SAP recovered with parent; targeted endpoint alignment, not full reanalysis. | Multiple outcomes, drugs, timepoints and subgroups. | Day-10 and rebound intervals cross no effect. | Summary says one-third lower rebound risk despite imprecise OR; avoid definitive wording.','No head-to-head comparison with other antivirals.'),
('Eligibility; Discussion','Early acute COVID-19 in selected adults. | IR course as tested. | Supports a nasal-RNA signal only. | Does not prove lower contagion, long-COVID treatment or superiority to other drugs.','Cross-trial viral-load rankings are not valid comparative efficacy.'),
('NCT04510194','COVID-OUT. | Acute and long-term companion reports. | Same randomized cohort subset. | Current trial-family reconciliation.','One family, three reports.'),
('Byline; Notes; conflicts','Carolyn Bramante, Kenneth Beckman and colleagues. | US multicenter COVID-OUT group. | Same foundation funding; authors state funders had no role. | Other factorial drug donations listed; metformin supply not independently characterized. | Named consulting, grant, stock and advisory disclosures include Buse, Puskarich, Karger, Cohen and Bramante.','Documented without imputing misconduct.'),
('Full published report','Clinical Infectious Diseases 2024, DOI 10.1093/cid/ciae159. | Full article acquired. | GAP: Virology-specific supplementary tables/figures not separately recovered in this assessment. | NCT04510194 and parent protocol/SAP available. | No virology correction identified in retrieved records. | November 3–4, 2026.','Main effect and its uncertainty directly inspected.'),
('G-METFORMIN mechanism/infection','Antiviral rationale. | Supports an RNA-load reduction; indirect for clinical prevention. | Authors’ mechanistic explanation is plausible but not proven mediation.','Do not count as independent replication of long-term benefit.'),
('Synthesis','Metformin lowered average nasal RNA load in this substudy. | Infectious-virus effects, transmission and mediation are unresolved. | Independent virology with culture plus clinical outcomes could clarify relevance.','Rebound reduction remains uncertain.')
], 'The randomized comparison supports a modest RNA-load effect in an optional substudy, subject to missingness and selection. It does not directly establish infectivity, transmission or clinical benefit and shares its trial family with the other COVID-OUT reports.')

compact('COND-C15-MA32-METABOLIC','MA.32 metabolic companion: improved biomarkers without established cancer benefit',[
('Introduction; Methods','Measure weight and metabolic effects of metformin and possible SNP modification. | Planned companion analyses; primary parent endpoint was invasive disease-free survival. | Six-month metabolic response.','This report predates the definitive cancer-outcome report.'),
('Results; Figure 1; Table 1','Nondiabetic adults with high-risk operable breast cancer. | International MA.32 participants still taking study drug with paired fasting bloods. | 3649 randomized; metabolic subset 2915: 1412 metformin, 1503 placebo; SNP subset 2747.','734 randomized participants are absent from the metabolic cohort.'),
('Methods','Metformin 850 mg caplets; matching placebo. | Once daily for four weeks then twice daily; intended five years. | Standard surgery and systemic/radiation cancer therapies. | Baseline to six months in this analysis.','Different follow-up from the final cancer trial.'),
('Study design','Placebo. | Parent 1:1 assignment. | Computer-generated randomization. | Double-blind; laboratory assays blinded to allocation. | Paired baseline and on-treatment sampling.','Selection after randomization limits a simple ITT interpretation.'),
('Laboratory; statistical methods','Weight, glucose, insulin, HOMA, leptin, hsCRP; interaction analyses. | Central insulin/leptin/hsCRP assays with 10% repeats; local glucose. | Six months. | Intermediate metabolic measures, not cancer recurrence. | NR: Clinical-benefit thresholds not established for these changes.','No surrogate validation for anticancer benefit.'),
('Table 2','Median weight change −1.4 kg versus +.5 kg. | Weight-change n=1394 versus 1499; metabolic subset n=1412/1503. | Adjusted metformin/placebo ratios: insulin .85, HOMA .83, leptin .80, hsCRP .84. | Weight standardized ratio .97, CI .97–.98; ratios adjust baseline, age and BMI. | Reported P<.0001 for these comparisons; no qualitative SNP interaction.','Raw within-arm percentages and adjusted between-arm ratios are different quantities.'),
('Table 1; limitations','Postrandomization exclusion of those without paired on-treatment samples. | More metformin-assigned and Black participants excluded; diet/activity missing in over 75%. | Required on-drug status, but short-term dosing compliance uncertain. | 412 metformin and 322 placebo excluded from metabolic cohort. | Available paired samples, not full randomized ITT. | Individual participant.','Selection may distort effect magnitude and generalizability.'),
('Limitations; final MA.32 companion','No new comprehensive safety analysis in this paper. | Selected metabolic cohort is not an unbiased safety denominator. | Authors state toxicity/compliance data were unavailable until efficacy analysis. | Drug-related discontinuation may contribute to exclusions. | Six-month biomarker window.','Use the later parent report for harms, retaining its numerical discrepancies.'),
('Methods; limitations','Conditioning on on-treatment samples and multiple biomarkers. | Randomization helps, but selection and unmeasured lifestyle changes remain. | Parent primary clinical endpoint explicitly deferred. | Multiple biomarker and interaction tests without a stated family-wise correction. | Large biomarker sample, but no clinical-outcome estimate here. | Printed HOMA formula units are inconsistent with conventional dimensional form; do not use it as a calculation instruction.','Metabolic findings cannot validate a cancer-prevention claim.'),
('Discussion','Selected nondiabetic breast-cancer population. | 1700 mg/day after ramp-up. | Supports metabolic change in this setting. | Not evidence of survival benefit, healthy-person longevity or a validated genetic prescribing rule.','Later clinical results take precedence for clinical claims.'),
('NCT01101438','CCTG MA.32. | Final COND-C15-MA32-2022 and earlier 492-person safety analysis. | Same trial, overlapping samples. | Current family reconciliation.','Do not count as an independent positive cancer trial.'),
('Acknowledgments; competing interests','Pamela Goodwin, Bingshu Chen, Marguerite Ennis and colleagues. | CCTG and central Toronto laboratories. | Public/cancer-charity support; statement of no sponsor role in this report. | Apotex in-kind metformin/placebo. | Roche employment and several oncology-industry grants/honoraria disclosed.','Funding statements are report-specific.'),
('Article and two supplements','npj Breast Cancer 2021, DOI 10.1038/s41523-021-00275-z. | Full XML and supplements acquired. | Supplement 1 is an interaction table; supplement 2 is a reporting summary, not the full trial protocol/SAP. | NCT01101438, first posted April 12, 2010 according to report. | No correction identified in retrieved records; clinical follow-up published in 2022. | November 3–4, 2026.','Corrects the earlier mistaken classification of these files as protocol/SAP.'),
('G-METFORMIN breast-cancer/mechanism','Biomarkers versus cancer outcomes. | Metabolic improvement supported, anticancer benefit not established. | Authors anticipated possible clinical benefit; later primary report was negative.','Do not preserve an outdated “outcomes forthcoming” statement.'),
('Synthesis','Improved insulin and weight measures did not establish improved cancer outcomes. | Mechanistic mediation and selected subgroups require direct testing. | Clinical outcomes, not biomarker changes alone, could change treatment conclusions.','One trial can improve biomarkers while failing its clinical endpoint.')
], 'A large but selected paired-sample analysis supports metabolic effects. It is not independent cancer-efficacy evidence, and the subsequent negative clinical endpoint prevents interpreting improved biomarkers as proven cancer benefit.')
